import{_ as e,o as r,c as a,a2 as l}from"./chunks/framework.E8pQZ6KS.js";const u=JSON.parse('{"title":"安全实验平台","description":"","frontmatter":{},"headers":[],"relativePath":"实验与实践/安全实验平台.md","filePath":"实验与实践/安全实验平台.md","lastUpdated":1792430298000}'),o={name:"实验与实践/安全实验平台.md"};function d(h,t,i,n,c,b){return r(),a("div",null,[...t[0]||(t[0]=[l('<h1 id="安全实验平台" tabindex="-1">安全实验平台 <a class="header-anchor" href="#安全实验平台" aria-label="Permalink to &quot;安全实验平台&quot;">​</a></h1><blockquote><p>网安学习 70% 靠动手。这里汇总校内外的实验环境与靶场，全部为<strong>授权环境</strong>，放心练习。</p></blockquote><h2 id="校内平台" tabindex="-1">校内平台 <a class="header-anchor" href="#校内平台" aria-label="Permalink to &quot;校内平台&quot;">​</a></h2><ul><li>网络安全虚拟仿真实验系统（网络空间安全创新实训平台）</li><li>信息安全实训平台（含 Web、密码、取证等模块）</li><li>网络舆情监测系统、物联网安全智能监控平台</li><li>以上设备均依托学院实验中心，课程实训中使用</li></ul><h2 id="自建靶场-推荐本地搭建" tabindex="-1">自建靶场（推荐本地搭建） <a class="header-anchor" href="#自建靶场-推荐本地搭建" aria-label="Permalink to &quot;自建靶场（推荐本地搭建）&quot;">​</a></h2><table tabindex="0"><thead><tr><th>靶场</th><th>说明</th></tr></thead><tbody><tr><td>DVWA（<a href="https://github.com/digininja/DVWA" target="_blank" rel="noreferrer">github.com/digininja/DVWA</a>）</td><td>Web 漏洞靶场，入门首选，一条 Docker 命令启动</td></tr><tr><td>pikachu</td><td>中文 Web 漏洞靶场，适合新手</td></tr><tr><td>WebGoat（<a href="https://github.com/WebGoat/WebGoat" target="_blank" rel="noreferrer">github.com/WebGoat/WebGoat</a>）</td><td>OWASP 官方教学靶场</td></tr><tr><td>Metasploitable 2</td><td>漏洞主机镜像，配合 <a href="./../必学工具/虚拟机与Kali.html">虚拟机与 Kali</a> 使用</td></tr><tr><td>VulnHub（<a href="https://www.vulnhub.com/" target="_blank" rel="noreferrer">vulnhub.com</a>）</td><td>各种难度靶机镜像，进阶练习</td></tr></tbody></table><h2 id="在线平台" tabindex="-1">在线平台 <a class="header-anchor" href="#在线平台" aria-label="Permalink to &quot;在线平台&quot;">​</a></h2><table tabindex="0"><thead><tr><th>平台</th><th>说明</th></tr></thead><tbody><tr><td>TryHackMe（<a href="https://tryhackme.com/" target="_blank" rel="noreferrer">tryhackme.com</a>）</td><td>引导式学习，新手友好</td></tr><tr><td>HackTheBox（<a href="https://www.hackthebox.com/" target="_blank" rel="noreferrer">hackthebox.com</a>）</td><td>进阶靶机，社区活跃</td></tr><tr><td>pwn.college（<a href="https://pwn.college/" target="_blank" rel="noreferrer">pwn.college</a>）</td><td>二进制/利用方向系统课程 + 自动评测</td></tr><tr><td>PortSwigger Academy（<a href="https://portswigger.net/web-security" target="_blank" rel="noreferrer">portswigger.net/web-security</a>）</td><td>Web 安全官方免费课程 + 实验</td></tr><tr><td>OverTheWire（<a href="https://overthewire.org/" target="_blank" rel="noreferrer">overthewire.org</a>）</td><td>命令行/协议闯关（Bandit 等）</td></tr></tbody></table><h2 id="使用规范" tabindex="-1">使用规范 <a class="header-anchor" href="#使用规范" aria-label="Permalink to &quot;使用规范&quot;">​</a></h2><div class="warning custom-block"><p class="custom-block-title">WARNING</p><ul><li>所有平台均为授权环境，练习产生的数据（payload、样本）不得用于真实目标；</li><li>恶意代码样本只在隔离虚拟机分析（见 <a href="./../安全方向/恶意代码分析.html">恶意代码分析</a>）；</li><li>校内平台遵守实验室管理规定。</li></ul></div>',10)])])}const _=e(o,[["render",d]]);export{u as __pageData,_ as default};
